CREATE OR REPLACE FUNCTION calculate_size_compatibility(p_donor_id TEXT, p_recipient_id TEXT)
RETURNS NUMERIC AS $$
DECLARE
    v_donor_bmi NUMERIC;
    v_recip_bmi NUMERIC;
    v_score NUMERIC;
BEGIN
    -- Get donor BMI from physicalstats JSON column
    SELECT (d.physicalstats->>'Bmi_Value')::NUMERIC
    INTO v_donor_bmi
    FROM demographics d
    WHERE d.contrib_registry = p_donor_id;

    -- Get recipient BMI directly
    SELECT r.bmi_val
    INTO v_recip_bmi
    FROM recipients_demographics r
    WHERE r.recip_registry = p_recipient_id;

    -- Handle missing BMI values
    IF v_donor_bmi IS NULL OR v_recip_bmi IS NULL THEN
        RETURN NULL;
    END IF;

    -- Calculate size compatibility score: S_size = 1 - |BMI_donor / BMI_recipient - 1|
    v_score := 1 - ABS(v_donor_bmi / v_recip_bmi - 1);

    RETURN v_score;
END;
$$ LANGUAGE plpgsql;

