CREATE OR REPLACE FUNCTION calculate_size_compatibility(p_donor_id TEXT, p_recipient_id TEXT)
RETURNS NUMERIC AS $$
DECLARE
    v_donor_bmi NUMERIC;
    v_recip_bmi NUMERIC;
BEGIN
    SELECT CAST((d.physicalstats->>'Bmi_Value') AS NUMERIC)
    INTO v_donor_bmi
    FROM demographics d
    WHERE d.contrib_registry = p_donor_id;

    SELECT r.bmi_val
    INTO v_recip_bmi
    FROM recipients_demographics r
    WHERE r.recip_registry = p_recipient_id;

    IF v_donor_bmi IS NULL OR v_recip_bmi IS NULL OR v_recip_bmi = 0 THEN
        RETURN NULL;
    END IF;

    RETURN 1 - ABS(v_donor_bmi / v_recip_bmi - 1);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_size_compatibility(p_donor_id TEXT, p_recipient_id TEXT)
RETURNS NUMERIC AS $$
DECLARE
    score NUMERIC;
BEGIN
    SELECT 1.0 - ABS(CAST(d.physicalstats->>'Bmi_Value' AS NUMERIC) / r.bmi_val - 1.0)
    INTO score
    FROM demographics d, recipients_demographics r
    WHERE d.contrib_registry = p_donor_id
      AND r.recip_registry = p_recipient_id;

    IF score IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN score;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION calculate_size_compatibility(p_donor_id TEXT, p_recipient_id TEXT)
RETURNS NUMERIC AS $$
