    donor_bmi REAL;
    recip_bmi REAL;
BEGIN
    SELECT physicalstats->>'Bmi_Value'::REAL INTO donor_bmi FROM demographics WHERE contrib_registry = p_donor_id;
    SELECT bmi_val INTO recip_bmi FROM recipients_demographics WHERE recip_registry = p_recipient_id;

    IF donor_bmi IS NULL OR recip_bmi IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN 1 - ABS(donor_bmi / recip_bmi - 1);
END;
$$ LANGUAGE plpgsql;

